const SNOOZE = [
  { id: "later", label: "Later today, 16:00", icon: "clock" },
  { id: "tomorrow", label: "Tomorrow, 09:00", icon: "sun", hint: "S" },
  { id: "monday", label: "Monday, 09:00", icon: "calendar" },
];

<SplitButton
  label="Snooze"
  variant="secondary"
  items={SNOOZE}
  onClick={() => snooze("tomorrow")}
  onSelect={(id) => snooze(id)}
  aria-keyshortcuts="S"
/>

{/* half of a phone dock, beside a Button: same height, each fills its cell */}
<div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
  <Button label="Send back" variant="secondary" size="lg" fullWidth onClick={openSendBack} />
  <SplitButton label="Snooze" variant="secondary" size="lg" fullWidth align="end" items={SNOOZE} onClick={() => snooze("tomorrow")} onSelect={(id) => snooze(id)} />
</div>
